/// One ME3-loadable DLL, as a row in the picker.
///
/// `Debug` is derived because these appear in test assertions, and a failing test that can only
/// say "two values differ" costs more than the derive does.
#[derive(Debug)]
pub struct Mod {
    /// Cargo package name -- the key both source tables agree on.
    pub package: &'static str,
    /// File to copy next to the game, and to name in the `[[natives]]` entry.
    pub artifact: &'static str,
    pub label: &'static str,
    pub blurb: &'static str,
    pub category: &'static str,
    /// `player` or `diagnostic`. Diagnostics are never ticked on a first run.
    pub audience: &'static str,
    pub default_on: bool,
    /// Inert, or refusing to arm, unless Seamless Co-op is loaded.
    pub needs_seamless: bool,
    /// Recorded in the conflict table as something a player must ask for by name.
    pub opt_in_only: bool,
    /// Bigger mods that already carry this one. Empty for most. Ticking this beside any of
    /// them puts two copies of one feature in the game, so the picker refuses the pair.
    pub included_in: &'static [&'static str],
    /// The file in the game directory this mod reads, when it has one.
    pub config: Option<&'static str>,
}

/// A pair that must never share one profile, and why, in words a player can act on.
#[derive(Debug)]
pub struct Conflict {
    pub a: &'static str,
    pub b: &'static str,
    /// The failure mode, as recorded in `scripts/me3-dll-conflicts.toml`.
    pub kind: &'static str,
    pub explanation: &'static str,
}

